Perhatikan potongan program berikut: var
nilai : array[1..10] of integer = (1,7,9,23,12,6,12,7,8,10);

function rata2(n: integer):real;
var
 sum:real;
begin
 i:=1;
 sum := 0;
 repeat
 sum := sum+nilai[i];
 until (i=n);
 rata2:=sum/n;
end; Berapakah nilai yang dikembalikan jika dilakukan pemanggilan fungsi rata2(10)?

Perhatikan fungsi berikut function coba(a:integer):string;
var
 b : integer;
 str : string;
begin
 if (a=0) then
 coba:= ''
 else
 begin
 b := a mod 2;
 if (b=0) then str:='0'
 else str:='1';
 coba:= coba(a div 2)+str;
 end;
end; nilai yang dikembalikan oleh pemanggilan fungsi coba(155) adalah?

